//! Milestone A acceptance tests.
//!
//! The known-answer vectors below were generated by
//! `reference/reference_workload.py`, an independent transcription of the
//! algorithm that shares no code with the Rust implementation. Agreement
//! between the two is the evidence that the workload is correctly specified;
//! it is not merely a snapshot of whatever the Rust happened to produce.
//!
//! If you change `src/workload.rs` semantics, these tests SHOULD fail. Do not
//! "fix" them by pasting in new values from the Rust. Re-derive them by running
//! `python3 reference/reference_workload.py` and confirm the two agree.

use fair_compute_bench::implementation_hash;
use fair_compute_bench::workload::{
    self, ParamError, Params, MAX_WORDS, MIN_WORDS,
};

/// (seed, scratchpad_words, steps, expected digest hex)
const KAT: &[(u64, u64, u64, &str)] = &[
    (
        0,
        1024,
        10_000,
        "898d0f747b85e8c4e14d3139cf85723946c2a3a5caf87093153263f8d698a4d8",
    ),
    (
        0,
        1024,
        10_001,
        "4dcff0af62e97a257530d8f5f09ff656a09b980857738fff3a832399597a1767",
    ),
    (
        1,
        1024,
        10_000,
        "e47daa135f3f80ee5f430c033482fad6f1bf2f3aa7d5b251b6bac3b3e40ee9f0",
    ),
    (
        0xDEAD_BEEF_CAFE_F00D,
        4096,
        100_000,
        "d2cf0d099685b3dc5746b1943047b8af89efa3062305a24bb80ed023655be3c6",
    ),
    (
        0x0123_4567_89AB_CDEF,
        65536,
        250_000,
        "718fcb7c78b1a0f19151e3604bfec98b4a0f5181a7abfbe9a39a189f6d6f3199",
    ),
];

fn params(seed: u64, words: u64, steps: u64) -> Params {
    Params { seed, scratchpad_words: words, steps }
}

#[test]
fn matches_independent_reference_implementation() {
    for (seed, words, steps, expected) in KAT {
        let got = workload::execute(params(*seed, *words, *steps))
            .expect("KAT parameters are valid")
            .to_hex();
        assert_eq!(
            &got, expected,
            "\nKAT mismatch for seed=0x{:016x} words={} steps={}\n  expected {}\n  got      {}\n\
             The Rust implementation disagrees with reference/reference_workload.py.\n\
             One of them is wrong. Do not update this constant without re-deriving it.",
            seed, words, steps, expected, got
        );
    }
}

#[test]
fn repeated_execution_is_identical() {
    let p = params(0xABCD_EF01_2345_6789, 8192, 50_000);
    let a = workload::execute(p).unwrap();
    let b = workload::execute(p).unwrap();
    let c = workload::execute(p).unwrap();
    assert_eq!(a, b);
    assert_eq!(b, c);
}

#[test]
fn reinitialising_between_runs_restores_state() {
    // This is the property the harness depends on: run_chain mutates the
    // scratchpad, so run N+1 is only comparable to run N if the pad is
    // re-initialised first. If this test fails, every multi-run timing in the
    // harness is measuring a different workload each time.
    let p = params(7, 4096, 20_000);
    let mut pad = vec![0u64; p.scratchpad_words as usize];

    workload::init_scratchpad(&mut pad, p.seed);
    let first = workload::run_chain(&mut pad, p);

    // Without re-init, the second run starts from mutated state.
    let without_reinit = workload::run_chain(&mut pad, p);
    assert_ne!(
        first, without_reinit,
        "running twice without re-init produced the same digest; \
         the write-back path is probably dead"
    );

    workload::init_scratchpad(&mut pad, p.seed);
    let with_reinit = workload::run_chain(&mut pad, p);
    assert_eq!(first, with_reinit);
}

#[test]
fn every_parameter_affects_the_digest() {
    let base = workload::execute(params(0, 4096, 30_000)).unwrap();
    assert_ne!(base, workload::execute(params(1, 4096, 30_000)).unwrap(), "seed ignored");
    assert_ne!(base, workload::execute(params(0, 8192, 30_000)).unwrap(), "size ignored");
    assert_ne!(base, workload::execute(params(0, 4096, 30_001)).unwrap(), "steps ignored");
}

#[test]
fn scratchpad_is_actually_written() {
    // A workload whose write-back is optimised away degenerates into a
    // read-only chain, which has entirely different fairness properties.
    let p = params(42, 4096, 25_000);
    let mut pad = vec![0u64; p.scratchpad_words as usize];
    workload::init_scratchpad(&mut pad, p.seed);
    let before: Vec<u64> = pad.clone();
    let _ = workload::run_chain(&mut pad, p);
    let changed = pad.iter().zip(before.iter()).filter(|(a, b)| a != b).count();
    assert!(
        changed > 0,
        "no scratchpad slot changed; the read-modify-write was eliminated"
    );
}

#[test]
fn init_is_seed_dependent_and_repeatable() {
    let mut a = vec![0u64; 1024];
    let mut b = vec![0u64; 1024];
    let mut c = vec![0u64; 1024];
    workload::init_scratchpad(&mut a, 0);
    workload::init_scratchpad(&mut b, 0);
    workload::init_scratchpad(&mut c, 1);
    assert_eq!(a, b);
    assert_ne!(a, c);
    // A constant-fill init would make the chain trivially predictable.
    assert!(a.windows(2).any(|w| w[0] != w[1]), "init produced a constant fill");
}

#[test]
fn rejects_invalid_parameters() {
    assert_eq!(
        params(0, 3000, 100).validate(),
        Err(ParamError::NotPowerOfTwo(3000))
    );
    assert_eq!(
        params(0, 512, 100).validate(),
        Err(ParamError::TooSmall(512))
    );
    assert_eq!(
        params(0, MAX_WORDS * 2, 100).validate(),
        Err(ParamError::TooLarge(MAX_WORDS * 2))
    );
    assert_eq!(params(0, MIN_WORDS, 0).validate(), Err(ParamError::ZeroSteps));
    assert!(params(0, MIN_WORDS, 1).validate().is_ok());
}

#[test]
fn scratchpad_ceiling_is_addressable_on_wasm32() {
    // Milestone B compiles this same source to wasm32, where usize is 32 bits.
    // If MAX_WORDS ever exceeds u32::MAX the `as usize` narrowing in run_chain
    // becomes a silent truncation rather than a safe cast.
    assert!(
        MAX_WORDS <= u32::MAX as u64,
        "MAX_WORDS exceeds wasm32 addressable range"
    );
}

#[test]
fn mix_is_a_permutation_on_sampled_inputs() {
    // Not a proof, but a cheap guard against a transcription error that
    // collapses the mixer onto a small output set.
    use std::collections::HashSet;
    let mut seen = HashSet::new();
    for i in 0..100_000u64 {
        assert!(seen.insert(workload::mix(i)), "mix collided at {}", i);
    }
    assert_eq!(workload::mix(0), workload::mix(0), "mix is not pure");
}

#[test]
fn implementation_hash_is_stable_and_nonempty() {
    let h = implementation_hash();
    assert_eq!(h.len(), 64);
    assert_eq!(h, implementation_hash());
    assert!(h.chars().all(|c| c.is_ascii_hexdigit()));
    assert_ne!(h, "0".repeat(64));
}
